param([string]$OutputPath)
$ErrorActionPreference = 'Stop'
if ([string]::IsNullOrWhiteSpace($OutputPath)) { $OutputPath = Join-Path $PSScriptRoot 'OpenAC.exe' }
$OutputPath = [System.IO.Path]::GetFullPath($OutputPath)
$compilerRoot = 'C:\Windows\Microsoft.NET\Framework64\v4.0.30319'
$sources = @('AssemblyInfo.cs','RogControl.cs','ShellStructure.cs','StructurePages.cs','AuraStructure.cs','SettingsStructure.cs','FanStructure.cs','DeviceStructure.cs','Monitoring.cs','GameLibrary.cs','DeviceGearLink.cs','StorageStructure.cs','NativeSettingsStructure.cs','SharedWriteBinding.cs','MacroEngine.cs','MacroFeatures.cs','LcdStructure.cs','AudioEndpointStructure.cs','ReceiverStructure.cs','FirmwareStructure.cs','GearExtendedStructure.cs','FanLightingStructure.cs','ScenarioProfiles.cs','ScenarioStructure.cs','LocalUpdateCatalog.cs','LocalUpdateStructure.cs','BoardArgbStructure.cs','DiscoveryStructure.cs','ControlPolicy.cs','LivePreviewState.cs','UiPreferences.cs','GitHubUpdateCatalog.cs','GitHubUpdateStructure.cs','AutoDeviceRead.cs','AsusDriverCatalog.cs','AsusUpdateStructure.cs','MonitoringModels.cs','MonitoringLayout.cs','WindowsTelemetry.cs','PreviewAssets.cs','AuraSyncCoordinator.cs','GearLinkLightingModelFacts.cs','AuraAnimation.cs','AuraAnimationLifecycle.cs','WindowsPower.cs','WindowsToolsStructure.cs','WindowsDisplay.cs','WindowsDisplayStructure.cs','WindowsBrightness.cs','WindowsBrightnessStructure.cs','FanNativeStructure.cs','WindowsBattery.cs','WindowsBatteryStructure.cs','NotebookStructure.cs','NotebookControlModel.cs','NotebookControlStructure.cs','MousePerformanceStructure.cs','OriginalPixelLayout.cs','KeyboardKeysStructure.cs','KeyboardViewsStructure.cs','GearPowerStructure.cs','KeyboardLightingStructure.cs','HeadsetAudioStructure.cs','GameFirstStructure.cs','GpuLightingStructure.cs','MouseButtonsStructure.cs','MouseLightingStructure.cs','MouseCalibrationZoneStructure.cs','MouseButtonActionFacts.cs','MouseCalibrationWorkflow.cs','DeviceHotplugStructure.cs')
$compileArgs = @('/nologo','/target:winexe','/platform:x64','/optimize+',('/win32manifest:' + (Join-Path $PSScriptRoot 'app.manifest')),('/out:' + $OutputPath),'/r:System.Management.dll','/r:System.ServiceProcess.dll','/r:System.Web.Extensions.dll','/r:System.Xaml.dll',('/r:' + $compilerRoot + '\WPF\PresentationFramework.dll'),('/r:' + $compilerRoot + '\WPF\PresentationCore.dll'),('/r:' + $compilerRoot + '\WPF\WindowsBase.dll'))
$compileArgs += $sources | ForEach-Object { Join-Path $PSScriptRoot $_ }
& (Join-Path $compilerRoot 'csc.exe') @compileArgs
if ($LASTEXITCODE -ne 0) { throw 'OpenAC compilation failed.' }
Write-Output 'OpenAC compilation succeeded.'
